const BOND_KEY="ignite-bond-v1";
const BOND_PROMPTS={daily:["Apa satu hal kecil yang membuatmu merasa dekat denganku hari ini?","Kalau malam ini hanya punya satu jam bersama, kamu ingin menghabiskannya bagaimana?","Apa momen kecil kita akhir-akhir ini yang ingin kamu ulang?","Hal apa dari pasanganmu yang akhir-akhir ini paling kamu hargai?"],deep:["Apa hal tentang masa depan kita yang paling ingin kamu bangun bersama?","Kapan kamu merasa paling aman untuk menjadi dirimu sendiri bersamaku?","Apa sesuatu yang ingin kamu pelajari tentang pasanganmu tahun ini?","Apa satu kebiasaan kecil yang bisa membuat hubungan kita terasa lebih hangat?"],quiz:["Siapa yang lebih mungkin mengajak liburan dadakan?","Siapa yang lebih cepat bilang ayo coba saat ada hal baru?","Siapa yang biasanya lebih dulu mencairkan suasana setelah salah paham?"]};
function readBond(){try{const raw=JSON.parse(localStorage.getItem(BOND_KEY)||"{}");return{...raw,favorites:Array.isArray(raw?.favorites)?raw.favorites:[],goals:Array.isArray(raw?.goals)?raw.goals:[]}}catch{return{favorites:[],goals:[]}}}
function writeBond(v){localStorage.setItem(BOND_KEY,JSON.stringify(v));return v}
function pickBond(type,current=""){const pool=BOND_PROMPTS[type]||BOND_PROMPTS.daily;const choices=pool.filter(x=>x!==current);return choices[Math.floor(Math.random()*choices.length)]||pool[0]}
function renderBond(){
 const b=readBond(),current=b.dailyCurrent||pickBond("daily"),deep=b.deepCurrent||pickBond("deep"),quiz=b.quizCurrent||pickBond("quiz");
 if(!b.dailyCurrent)b.dailyCurrent=current;
 if(!b.deepCurrent)b.deepCurrent=deep;
 if(!b.quizCurrent)b.quizCurrent=quiz;
 writeBond(b);
 let html='<section class="bond-v1"><div class="bond-v1-top"><div></div><div class="brand">BOND</div><div></div></div><section class="bond-v1-hero"><div class="eyebrow">CONNECTION, BEYOND THE GAME</div><h1>Make space<br>for each other.</h1><p>Small questions can become big memories.</p></section><section class="bond-v1-grid">';
 html+='<article class="bond-v1-card featured"><span class="eyebrow">DAILY QUESTION</span><h3>'+esc(current)+'</h3><div><button class="btn ghost" data-bond-action="new" data-bond-type="daily">Another</button><button class="btn primary" data-bond-action="favorite">Save</button></div></article>';
 html+='<article class="bond-v1-card"><span class="bond-v1-icon">◌</span><span class="eyebrow">COUPLE QUIZ</span><h3>'+esc(quiz)+'</h3><button class="btn ghost" data-bond-action="new" data-bond-type="quiz">New Question</button></article>';
 html+='<article class="bond-v1-card"><span class="bond-v1-icon">✦</span><span class="eyebrow">DEEP TALK</span><h3>'+esc(deep)+'</h3><button class="btn ghost" data-bond-action="new" data-bond-type="deep">Go Deeper</button></article>';
 html+='<article class="bond-v1-card"><span class="bond-v1-icon">♡</span><span class="eyebrow">FAVORITES</span><h3>'+b.favorites.length+' saved</h3><div class="bond-favorites">'+(b.favorites.length?b.favorites.map(x=>'<p>'+esc(x)+'</p>').join(""):'<p>Save questions you want to revisit.</p>')+'</div></article>';
 html+='<article class="bond-v1-card goals"><span class="bond-v1-icon">∞</span><span class="eyebrow">RELATIONSHIP GOALS</span><h3>Small things, together.</h3><form id="bond-goal-form"><input name="goal" maxlength="100" placeholder="Add a small goal"><button class="btn primary full">Add Goal</button></form><div class="bond-goals">'+(b.goals.length?b.goals.map((g,i)=>'<label><input type="checkbox" data-bond-goal="'+i+'" '+(g.done?"checked":"")+'><span>'+esc(g.text)+'</span></label>').join(""):'<p class="muted">No goals yet.</p>')+'</div></article>';
 html+='</section>'+renderBottomNav("home")+'</section>';app.innerHTML=html;
}
